import 'package:flutter/material.dart';
import '../../core/api/api_client.dart';

enum AppRole { customer, driver }
class HomeScreen extends StatefulWidget { const HomeScreen({super.key,required this.api,required this.onSignedOut}); final ApiClient api; final VoidCallback onSignedOut; @override State<HomeScreen> createState()=>_HomeScreenState(); }
class _HomeScreenState extends State<HomeScreen>{AppRole role=AppRole.customer;@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(role==AppRole.customer?'Customer dashboard':'Driver dashboard'),actions:[PopupMenuButton<AppRole>(initialValue:role,onSelected:(value)=>setState(()=>role=value),itemBuilder:(_)=>const[PopupMenuItem(value:AppRole.customer,child:Text('Customer mode')),PopupMenuItem(value:AppRole.driver,child:Text('Driver mode'))]),IconButton(onPressed:()async{await widget.api.logout();widget.onSignedOut();},icon:const Icon(Icons.logout))]),body:role==AppRole.customer?const _CustomerHome():const _DriverHome());}
class _CustomerHome extends StatelessWidget{const _CustomerHome();@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[const Card(child:ListTile(leading:Icon(Icons.verified_user_outlined),title:Text('Identity and KYC'),subtitle:Text('Verify email and upload address proof'))),const Card(child:ListTile(leading:Icon(Icons.calendar_month),title:Text('Book a future vehicle'),subtitle:Text('One-way, round-trip, airport, hourly or day booking'))),const Card(child:ListTile(leading:Icon(Icons.tour),title:Text('Holiday packages'),subtitle:Text('Bus, full vehicle and seat packages'))),const Card(child:ListTile(leading:Icon(Icons.local_taxi),title:Text('Online driver'),subtitle:Text('Realtime rides become available when dispatch is configured')))]);}
class _DriverHome extends StatelessWidget{const _DriverHome();@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[const Card(child:ListTile(leading:Icon(Icons.badge_outlined),title:Text('Driver compliance'),subtitle:Text('Documents, expiry and work eligibility'))),const Card(child:ListTile(leading:Icon(Icons.toggle_on),title:Text('Availability'),subtitle:Text('Go online only when eligible'))),const Card(child:ListTile(leading:Icon(Icons.route),title:Text('Assigned and active rides'),subtitle:Text('Offers, arrival, trip PIN, start and completion')))]);}
